  Widget build(BuildContext context) => Tooltip(
        message: 'Attach files (text)',
        child: InkWell(
          onTap: enabled ? onTap : null,
          borderRadius: BorderRadius.circular(6),
          child: Container(
            width: 48,
            height: 48,
            padding: const EdgeInsets.all(6),
